"""Frozen group-aware array tasks added in preview0.8; no generated-code repairs."""
from pathlib import Path
import hashlib,importlib.util,importlib.metadata,json,os,subprocess,sys,time
import numpy as np
from expansion import ROOT as R,MODELS,adapter,sha,validate_code
BRIEFS={
'K04':'''Assign curated human cortical-layer labels from prepared spatial transcriptomic spot expression. Each row is a tissue spot, not a cell. train_x=(33086,500),test_x=(14243,500). Training uses all eight sections of donors Br5292 and Br5595; test all four sections of the independent donor Br8100. train_groups gives two training donor IDs for donor-held-out validation; test IDs and section groups are scorer-only. Classes0..6 correspond to L1,L2,L3,L4,L5,L6,white matter. Some layers are absent in one training donor: grouped folds can lack classes, so handle this. Return one integer label0..6 pertest row. Primary metric averages seven-class macro-F1 equally across the four test sections; all seven labels fixed in every section. These four sections are one donor, not four independent people. The annotations were curated with histology and expression assistance; no fully orthogonal molecular-groundtruth claim.\nInputs are log1p(count/full33538-gene-librarytotal*10000). Exactly500 non-mitochondrial genes are selected by variance using all OUTER training spots only; the shared selection is not repeated inside inner validation. Features have the same gene order across rows. No coordinates, images, identifiers or layer markers selected using test labels are passed. This is supervised expression-to-layer transfer, not unsupervised spatial clustering or raw-histology segmentation. Fit all further transforms/hyperparameters on training donors only. Fixed per-row calculations allowed; never fit normalization or use neighboring test rows/batch adaptation. Do not concatenate rows as a tissue image. Use train_groups when validating. Gene symbols/IDs are given below in exact column order.''',
'M01':'''Predict real mouse choices conditional on the current visual stimulus, known experimenter block prior, and five previously observed choices/feedbacks. This is one-step conditional probability prediction, not cognitive parameter recovery or autonomous behavioral rollout. train_groups supplies training mouse IDs for mouse-held-out validation; test mouse IDs are scorer-only. Return a finite probability P(source choice+1)=P(turnCW),one pertest row, in[0,1]. Label0sourcechoice-1(turnCCW),label1sourcechoice+1(turnCW); do not assume sign mapping from left/right, learn it from training.\nInputs13columns: contrastLeft,contrastRight,probabilityLeft,previous_choice_lag1..lag5,previous_feedback_lag1..lag5. Contrasts/blockprior in0..1; absent-side contrast=0. Past choices-1/0/+1 (0nonresponse/missing),pastfeedback-1/0/+1 (0missing). Only past responses/feedback are supplied; current/future choice, feedback, reaction time, inclusion mask, identifiers and session performance are excluded. The known block prior is experimenter metadata, not an explicitly cued animal input.\nAll100 archived animals use their latest structurally complete session by date/run/lab and first≤1000source trials. Fixed nonoverlapping six-trial blocks supply targettrial5,11,17,...with five preceding observations. Target nonresponses or invalid current contrast/prior are excluded by a fixed structural rule. Crucially, no scored test target occurs in any other test example's history. Train83mice/7696examples,test17mice/1842examples,hash-based mouse-disjoint split; nine labs appear on both sides, NOT held-out labs. Mice are weighted equally in the primary binary log-loss: compute pertestmouse meannegative log-likelihood then average mice. Scorerclipsprobabilities to[1e-6,1-1e-6]. Lowerbetter. TraininggroupIDspermitpropervalidation. No joining, ordering, matching or reconstructing examples/trials; each already has its permitted context. Fit all transformations and supervised choices on training mice only, with deterministic seeds.'''
}
def freeze(task):
 d=R/f'experiments/{task}';a=adapter(task);x,y,xt,_=a.load();meta=json.loads((R/f'data/cache/{task}/metadata.json').read_text())
 context={k:meta[k] for k in ['feature_names','gene_ids','label_encoding','units'] if k in meta}
 prompt='Single-shot neuroscience code-construction experiment. Do not call tools, browse, read files or execute during generation. Return only JSON fields description and code.\n\nImplement fit_predict(train_x,train_y,test_x,train_groups).\n\n'+BRIEFS[task]+'\n\nPrepared context: '+json.dumps(dict(train_x_shape=list(x.shape),train_y_shape=list(y.shape),test_x_shape=list(xt.shape),**context))+'''\n\nAllowed imports numpy,scipy,sklearn,math,collections,functools,itertools,statistics,gc. No file/network/subprocess access, dynamic exec/eval, pretrained assets or specialist packages. One submission, no execution feedback. Entire fit_predict call must finish in180seconds on one numerical CPUthread, approximately4GB requested memory (not enforced). Keep code below240lines including blanks; deterministic seeds. Return complete self-contained Python code and concise description of training/validation policy. Do not claim a score.\n'''
 (d/'prompt.txt').write_text(prompt);(d/'response_schema.json').write_text(json.dumps(dict(type='object',properties=dict(description=dict(type='string'),code=dict(type='string')),required=['description','code'],additionalProperties=False)))
 spec=dict(benchmark_id=task,run_id='expansion-v1',date='2026-10-30',track='T3',models=MODELS,generation_replicates=1,reasoning_effort='high',timeout_seconds=180,line_limit_exclusive=240,memory_enforced=False,prompt_sha256=sha(d/'prompt.txt'),adapter_sha256=sha(d/'adapter.py'),data_sha256=sha(R/f'data/cache/{task}/data.npz'),protocol_sha256=sha(d/'protocol.md'),specialist_sha256=sha(d/'specialist.py'),metadata_sha256=sha(R/f'data/cache/{task}/metadata.json'),runner_sha256=sha(Path(__file__)),status='frozen before any evaluated model generation or method test score',test_targets_not_in_prompt=True)
 (d/'run-spec.json').write_text(json.dumps(spec,indent=2)+'\n');print(task,'frozen',flush=True)
def one(task,model):
 d=R/f'experiments/{task}';spec=json.loads((d/'run-spec.json').read_text())
 for path,key in [(d/'adapter.py','adapter_sha256'),(d/'protocol.md','protocol_sha256'),(d/'specialist.py','specialist_sha256'),(Path(__file__),'runner_sha256'),(R/f'data/cache/{task}/data.npz','data_sha256')]:assert sha(path)==spec[key],str(path)
 a=adapter(task);x,y,xt,truth=a.load();groups=a.train_groups();info={}
 if model in MODELS:
  obj=json.loads((d/(model+'.json')).read_text());code=obj['code'];validate_code(code);ns={};exec(compile(code,model,'exec'),ns);f=ns['fit_predict'];(d/(model+'.py')).write_text(code)
  info=dict(description=obj['description'],code_sha256=hashlib.sha256(code.encode()).hexdigest(),code_lines=len(code.splitlines()),line_limit_compliant=len(code.splitlines())<240)
 elif model=='task-baseline':f=a.baseline
 else:
  s=importlib.util.spec_from_file_location('specialist_'+task,d/'specialist.py');module=importlib.util.module_from_spec(s);s.loader.exec_module(module);f=module.fit_predict
  names=['singler','numpy'] if task=='K04' else ['scikit-learn','numpy','scipy'];info=dict(code_sha256=spec['specialist_sha256'],selection='Fixed before model generation and reference test score; no test tuning',packages={n:importlib.metadata.version(n) for n in names})
 np.random.seed(0);start=time.perf_counter();pred=np.asarray(f(x.copy(),y.copy(),xt.copy(),groups.copy()));seconds=time.perf_counter()-start;scored=a.score(pred,truth)
 p=R/f'results/predictions/{task}/expansion-v1--{model}.npz';p.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(p,predictions=pred)
 return dict(benchmark_id=task,slice_id='expansion-v1',model=model,status='measured',date='2026-10-30',track='T3' if model in MODELS else 'reference',reference_type='local_specialist_reproduction' if model=='singler' else 'local_domain_reference' if model=='behavioral-glm' else 'local_reproduction',n_units=len(scored['per_unit']),seconds=seconds,prediction_file=str(p.relative_to(R)),prediction_sha256=sha(p),input_sha256={f'data/cache/{task}/data.npz':spec['data_sha256']},prompt_sha256=spec['prompt_sha256'],superiority_eligible=False,superiority_reason='Custom source/split, one generation, current strongest specialist and matched total effort unestablished',**info,**scored)
def evaluate(task,reference_only=False):
 models=(['singler'] if task=='K04' else ['behavioral-glm']) if reference_only else MODELS+['task-baseline']+([] if task=='K04' else ['behavioral-glm'])
 p=R/f'results/{task}.json';rows=json.loads(p.read_text()) if p.exists() else [];env=dict(os.environ,OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1',VECLIB_MAXIMUM_THREADS='1',MKL_NUM_THREADS='1')
 for model in models:
  assert not any(r['model']==model for r in rows),'Preserve prior attempts; use a new explicit run for repetition'
  log=R/f'results/execution/{task}-expansion-v1-{model}.txt'
  try:
   out=subprocess.run([sys.executable,str(Path(__file__).resolve()),'one',task,model],capture_output=True,text=True,env=env,timeout=180);log.write_text(out.stdout+'\n'+out.stderr)
   if out.returncode:raise RuntimeError(out.stderr[-2000:])
   row=json.loads(out.stdout.strip().splitlines()[-1])
  except Exception as ex:row=dict(benchmark_id=task,slice_id='expansion-v1',model=model,status='failed',date='2026-10-30',reason=str(ex))
  rows.append(row);p.write_text(json.dumps(rows,indent=2)+'\n');print(task,model,row['status'],row.get('score'),flush=True)
if __name__=='__main__':
 action,task=sys.argv[1:3]
 if action=='freeze':freeze(task)
 elif action=='one':print(json.dumps(one(task,sys.argv[3])))
 else:evaluate(task,reference_only=action=='reference')
